import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const P=JSON.parse('{"title":"2019-10-17 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-10-17 -- Ceph Performance Meeting","date":"2019-10-17T00:00:00.000Z","updated":"2019-10-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","代码审查","CRUSH算法","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-17_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-10-17_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-10-17_-_-_Ceph_Performance_Meeting.md"};function l(s,o,p,a,_,g){return i(),t("div",null,[...o[0]||(o[0]=[r("<p>会议纪要：</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Bono、Radek、Eric、Adam、Patrick、Igor、Josh、Roman、Sue、Alex、Seifer等（具体姓名和职位未明确列出）</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>新提交的PR</strong>：</p><ul><li>Bono的PR：将Bono的缓存独立化，解决用户大量固定条目导致内存增长和性能下降的问题。</li><li>Radek的PR：降低Crimson的日志级别，可能用于性能提升。</li><li>Eric的PR：减少有序桶列表中的压力条目数量，提高效率。</li><li>Adam的PR：修复日志问题。</li><li>Patrick的PR：调整MDS缓存内存限制。</li><li>Igor的PR：短蓝存储工作，降低压缩放大。</li><li>Josh的PR：修复固定条目计算错误。</li></ul></li><li><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>Bono缓存独立化</strong>：该PR解决了用户大量固定条目导致的问题，但引入了额外的锁定竞争，需要通过增加缓存卡数量来缓解。</li><li><strong>4K金属信号</strong>：Igor的测试结果表明，4K金属信号在写入性能方面有显著提升，但读取性能有所下降。需要进一步测试和分析。</li><li><strong>I/O Uring引擎</strong>：Roman和Sue的测试结果表明，I/O Uring引擎在性能方面表现良好，但需要新的内核才能测试。</li></ul></li><li><p><strong>决定的事项</strong>：</p><ul><li>接受Bono缓存独立化PR，并采取措施缓解锁定竞争。</li><li>继续测试4K金属信号，并分析读取性能下降的原因。</li><li>接受I/O Uring引擎PR，但将其标记为实验性功能。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>Bono和Igor继续优化Bono缓存独立化和4K金属信号。</li><li>Roman和Sue继续测试I/O Uring引擎。</li><li>所有PR提交者继续修复代码问题。</li></ul></li></ol><p><strong>总结</strong>：</p><p>本次会议讨论了多个Ceph项目的进展和问题，并做出了相应的决策。会议强调了性能优化和代码质量的重要性，并要求相关人员进行进一步的工作。</p>",7)])])}const d=e(n,[["render",l]]);export{P as __pageData,d as default};
